def solve_n4():
    dp = [[[0]*2 for _ in range(3)] for _ in range(3)]
    dp[1][0][0] = 1
    dp[1][1][0] = 1
    dp[1][2][1] = 1

    for i in range(1, 2):
        for s in range(3):
            for y1 in range(2):
                if dp[i][s][y1] == 0: continue
                dp[i+1][0][y1] += dp[i][s][y1]
                if s != 1:
                    dp[i+1][1][y1] += dp[i][s][y1]
                if s != 2:
                    dp[i+1][2][y1] += dp[i][s][y1]

    total_count = 0
    for s in range(3):
        for y1 in range(2):
            if s == 1 and y1 == 1:
                continue
            total_count += dp[2][s][y1]
    print(total_count)

